    unitPrice: 8500,
    vatRate: 21,
  });

  assert.deepEqual(result.value.lines[1], {
    sku: 'DEV-HOUR',
    name: 'Development (hour)',
    qty: 3,
    unitPrice: 9500,
    vatRate: 21,
