});

test('invoiceTotals works with single line', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2024-01-15',
    status: 'draft',
    lines: [
      { sku: 'LOGO-PACK', qty: 1, unitPrice: 120000, name: 'Logo package', vatRate: 21, discountPercent: 0 },
    ],
  };

  const totals = invoiceTotals(invoice);
  assert.deepEqual(totals, { subtotal: 120000, discount: 0, total: 120000 });
});

test('invoiceTotals with real invoice from createInvoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 10 },
